//! Localisation infrastructure.
//!
//! Webex localises through Qt `.qm` language packs: the source language is English, every message lives in a
//! *context* (`QObject` = shared strings). This module reads those packs and offers the same lookup.
//!
//! ## What is shipped
//! * `src/assets/i18n/` - pure-Rust `.qm` reader ([`parse_qm`]), compact-pack reader, catalogs, language
//!   selection, argument substitution, locale date formatting, time zones.
//! * `assets/cisco/i18n/<code>.bin.z` (git-ignored, docs/cisco-assets.md) - 34 packs generated by
//!   `scripts/i18n/gen_i18n.py` (zlib of a compact format, ~1.1 MB in total, decoded lazily on first use of a language):
//!   * `de` = the full German pack (22.7k messages, 557 KB),
//!   * the other 33 = smaller packs (~1.07k messages each: shared `QObject` strings incl. all relative-time strings),
//!   * English (`en`) = identity, no pack.
//! * At run time a full pack of any locale is picked up when present and overlays the embedded
//!   one: `$WEBOX_I18N_DIR` or `%LOCALAPPDATA%\CiscoSparkLauncher\dynamic_dependencies\translations`,
//!   file `spark-windows-client.<code>.qm` (Qt .qm, parsed by [`parse_qm`]).
//! * `scripts/i18n/find_qm_context.py "<english>"` (`-s` substring, `-c <context>`, `--lang xx`) prints
//!   contexts + translations straight from the packs. `scripts/i18n/gen_i18n.py` regenerates `assets/cisco/i18n`.
//!
//! ## API
//! * [`tr`]`(context, source) -> Cow<str>` - translated text or the English source. Lookup order:
//!   `context`, then `QObject`, then any other context carrying the same source (deterministic).
//! * [`trn`]`(context, source, n) -> Cow<str>` - plural/numerus (`%n` is replaced by `n`; the form
//!   is chosen with the pack's Qt numerus rules; untranslated English: `%n` replaced only).
//! * App name (naming.rs, docs/naming.md): `tr`/`trn` fill `{{APP_NAME}}` and turn app-meaning "Webex" into
//!   [`APP_NAME`] ("Webox") from reviewed key lists; service-meaning strings keep "Webex". UI literals use `app_name!()`.
//! * [`args`]`(text, &[&dyn Display]) -> String` - substitutes `%1 %2 ...` (also `%L1`) and the JS
//!   style `{{0}} {{1}} ...` placeholders that the QObject strings use.
//! * Macros (crate root): `tr!("Ctx", "Source")` -> `Cow<str>`; `tr!("Ctx", "%1 of %2", a, b)` ->
//!   `String`; `trq!("Source" [, args])` (context `QObject` + fallback); `trn!("Ctx", "%n days", n)`.
//! * Language: [`set_language`]`("system" | "de" | "en_GB" | ...)`,
//!   [`active_code`], [`LANGUAGES`] (code + native name for the Settings dropdown),
//!   [`generation`] (bumps on every change), [`sync_from_settings`]`(ctx, &settings)` (call once per
//!   frame: reads settings key `language`, switches live and requests a repaint). `system` (default) = Windows UI language
//!   (`GetUserPreferredUILanguages`, then `GetUserDefaultLocaleName`; env `WEBOX_LANG` overrides) with
//!   the fallback chain `de-CH` -> `de_CH` -> `de` -> English.
//! * Dates: [`format_date_time`]`(ts_ms, DateStyle)` (local zone, locale of the active language:
//!   de `13.11.2026, 16:48`, en `11/13/2026, 4:48 PM`), [`format_date_time_in`] (explicit zone/locale,
//!   used by the tests), [`parse_iso_ms`], [`local_offset_secs`] (Windows `SystemTimeToTzSpecificLocalTime`, unix
//!   `localtime_r`; env `WEBOX_TZ_OFFSET_MIN` forces a fixed offset for screenshots).
//!
//! Notes: the Qt format is the documented .qm layout (hash/messages/contexts/numerus/language sections, tags
//! 1 End, 3 Translation, 6 Source, 7 Context, 8 Comment, numerus rule bytecode). Date patterns per locale are CLDR short
//! formats and the native language names are standard autonyms; the packs contain neither.

use std::borrow::Cow;
use std::collections::HashMap;
use std::fmt::Display;
use std::io::Read;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Mutex, OnceLock, RwLock};

// Languages and embedded packs.

/// A selectable UI language (35 locales). `native` = standard autonym.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Language {
    /// Pack/settings code (`de`, `en_GB`, `zh_TW` ...), the value stored under settings key `language`.
    pub code: &'static str,
    /// BCP-47 tag.
    pub bcp47: &'static str,
    /// Name in its own language, as shown in the Settings language dropdown.
    pub native: &'static str,
}

macro_rules! lang {
    ($c:expr, $b:expr, $n:expr) => {
        Language { code: $c, bcp47: $b, native: $n }
    };
}

