/// The languages with a pack. The packs are Webex files (`assets/cisco/i18n/<code>.bin.z`, docs/cisco-assets.md);
/// a build without them shows English.
const PACK_CODES: [&str; 33] = [
    "ar", "bg", "ca", "cs", "cy_GB", "da", "de", "en_GB", "es", "es_MX", "fr", "fr_CA", "ga", "he", "hr", "hu", "id_ID",
    "it", "ja", "ko", "nb", "nl", "pl", "pt", "ro", "ru", "sl", "sr", "sv", "tr", "uk", "zh", "zh_TW",
];

fn pack(code: &str) -> Option<&'static [u8]> {
    if !PACK_CODES.contains(&code) { return None; }
    crate::assets::cisco_assets::get(&format!("i18n/{code}.bin.z"))
}

/// Map any locale tag (`de-CH`, `de_DE.UTF-8`, `zh-Hant-TW`, `nn-NO`, `iw` ...) to the best pack code
/// via the chain full tag -> language, ending in `en`.
pub fn resolve_code(tag: &str) -> &'static str {
    let t = tag.split(['.', '@']).next().unwrap_or("").replace('_', "-");
    let parts: Vec<&str> = t.split('-').filter(|s| !s.is_empty()).collect();
    let Some(lang) = parts.first().map(|s| s.to_ascii_lowercase()) else { return "en" };
    let lang = match lang.as_str() {
        "no" | "nn" => "nb".to_string(),
        "iw" => "he".to_string(),
        "in" => "id".to_string(),
        o => o.to_string(),
    };
    let mut region = String::new();
    let mut script = String::new();
    for p in &parts[1..] {
        if p.len() == 4 {
            script = p.to_ascii_lowercase();
        } else if p.len() == 2 || (p.len() == 3 && p.chars().all(|c| c.is_ascii_digit())) {
            region = p.to_ascii_uppercase();
        }
    }
    if lang == "zh" {
        return if script == "hant" || ["TW", "HK", "MO"].contains(&region.as_str()) { "zh_TW" } else { "zh" };
    }
    let mut cands = vec![];
    if !region.is_empty() {
        cands.push(format!("{lang}_{region}"));
        if lang == "es" && region.len() == 3 {
            cands.push("es_MX".into()); // es-419
        }
    }
    cands.push(lang.clone());
    for c in &cands {
        if let Some(l) = LANGUAGES.iter().find(|l| l.code.eq_ignore_ascii_case(c)) {
            return l.code;
        }
    }
    "en"
}

fn pack_dirs() -> Vec<std::path::PathBuf> {
    let mut v = vec![];
    if let Ok(d) = std::env::var("WEBOX_I18N_DIR") {
        v.push(d.into());
    }
    if let Ok(d) = std::env::var("LOCALAPPDATA") {
        v.push(std::path::Path::new(&d).join("CiscoSparkLauncher/dynamic_dependencies/translations"));
    }
    v
}

fn load_catalog(code: &str) -> Option<Catalog> {
    let mut cat = pack(code).and_then(|z| Catalog::from_pack(z).ok());
    // de = the full embedded pack; other languages: overlay a full pack if present.
    if code != "de" {
        for dir in pack_dirs() {
            let f = dir.join(format!("spark-windows-client.{code}.qm"));
            if let Ok(bytes) = std::fs::read(&f) {
                if let Ok(qm) = parse_qm(&bytes) {
                    match &mut cat {
                        Some(c) => c.merge_qm(&qm),
                        None if code != "en" => cat = Some(Catalog::from_qm(&qm)),
                        None => {}
                    }
                    break;
                }
            }
        }
    }
    cat
}

fn catalog_for(code: &str) -> Option<&'static Catalog> {
    static CACHE: OnceLock<Mutex<HashMap<String, Option<&'static Catalog>>>> = OnceLock::new();
    let mut m = CACHE.get_or_init(Default::default).lock().unwrap();
    if let Some(c) = m.get(code) {
        return *c;
    }
    // Catalogs are leaked on purpose: at most one per language per process, and `tr` can then hand out `&'static str`.
    let c: Option<&'static Catalog> = load_catalog(code).map(|c| &*Box::leak(Box::new(c)));
    m.insert(code.to_string(), c);
    c
}

// Lookup API.

/// Translation from the active catalog (static lifetime), `None` when English / untranslated.
pub fn lookup(context: &str, source: &str) -> Option<&'static str> {
    let s = state().read().unwrap();
    s.catalog?.get(context, source)
}
/// Like [`lookup`] with the `QObject`/any-context fallback only (no context given).
pub fn lookup_any(source: &str) -> Option<&'static str> {
    lookup("QObject", source)
}

/// Translate `source` in `context`. Unknown strings and English return the source unchanged.
/// The app name is applied ([`brand`], naming.rs): `{{APP_NAME}}` is filled, app-meaning "Webex" becomes Webox.
pub fn tr<'a>(context: &str, source: &'a str) -> Cow<'a, str> {
    let t = match lookup(context, source) {
        Some(t) => Cow::Borrowed(t),
        None => Cow::Borrowed(source),
    };
    brand(context, source, t)
}

/// Plural-aware translation: picks the form for `n`, replaces `%n` with `n`.
#[allow(dead_code)] // the plural half of the lookup API (`trn!`); no plural string is shown yet
pub fn trn<'a>(context: &str, source: &'a str, n: i64) -> Cow<'a, str> {
    let t: &str = {
        let s = state().read().unwrap();
        s.catalog.and_then(|c| c.get_n(context, source, n)).unwrap_or(source)
    };
    let t = if t.contains("%n") {
        Cow::Owned(t.replace("%n", &n.to_string()))
    } else if std::ptr::eq(t.as_ptr(), source.as_ptr()) {
        Cow::Borrowed(source)
    } else {
        Cow::Owned(t.to_string())
    };
    brand(context, source, t)
}

/// Substitute `%1..%99` (optionally `%L1`) and `{{0}}..{{9}}` placeholders. Unreferenced args are ignored,
/// placeholders without an argument stay as they are. Qt semantics for `%1`: the digits are the
/// longest number that is a valid argument index.
pub fn args(text: &str, a: &[&dyn Display]) -> String {
    let mut out = String::with_capacity(text.len() + 16);
    let b = text.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' {
            let mut j = i + 1;
            if j < b.len() && b[j] == b'L' {
                j += 1;
            }
            let ds = j;
            while j < b.len() && b[j].is_ascii_digit() && j - ds < 2 {
                j += 1;
            }
            if j > ds {
                // Prefer the two-digit index only if valid.
                let mut idx: usize = text[ds..j].parse().unwrap();
                if j - ds == 2 && idx > a.len() {
                    j -= 1;
                    idx = text[ds..j].parse().unwrap();
                }
                if idx >= 1 && idx <= a.len() {
                    out.push_str(&a[idx - 1].to_string());
                    i = j;
                    continue;
                }
            }
        } else if b[i] == b'{' && text[i..].starts_with("{{") {
            if let Some(end) = text[i + 2..].find("}}") {
                if let Ok(k) = text[i + 2..i + 2 + end].trim().parse::<usize>() {
                    if k < a.len() {
                        out.push_str(&a[k].to_string());
                        i += 2 + end + 2;
                        continue;
                    }
                }
            }
        }
        let ch = text[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}

/// `tr!("Ctx", "Source")` -> `Cow<str>`; with arguments `tr!("Ctx", "%1 of %2", a, b)` -> `String`.
#[macro_export]
macro_rules! tr {
    ($ctx:expr, $src:expr) => { $crate::i18n::tr($ctx, $src) };
    ($ctx:expr, $src:expr, $($a:expr),+ $(,)?) => {
        $crate::i18n::args(&$crate::i18n::tr($ctx, $src), &[$(&$a as &dyn ::std::fmt::Display),+])
    };
}
/// Like `tr!` for strings without a known context (`QObject` + any-context fallback).
#[macro_export]
macro_rules! trq {
    ($src:expr) => { $crate::i18n::tr("QObject", $src) };
    ($src:expr, $($a:expr),+ $(,)?) => {
        $crate::i18n::args(&$crate::i18n::tr("QObject", $src), &[$(&$a as &dyn ::std::fmt::Display),+])
    };
}
/// `trn!("Ctx", "%n days", n)` -> `Cow<str>` with `%n` replaced; extra args are substituted as `%1..`.
#[macro_export]
macro_rules! trn {
    ($ctx:expr, $src:expr, $n:expr) => { $crate::i18n::trn($ctx, $src, ($n) as i64) };
    ($ctx:expr, $src:expr, $n:expr, $($a:expr),+ $(,)?) => {
        $crate::i18n::args(&$crate::i18n::trn($ctx, $src, ($n) as i64), &[$(&$a as &dyn ::std::fmt::Display),+])
    };
}

